/**
 * AgentWorkflowEngine Module
 * Extends WorkflowEngine with Agent system integration
 */

import { 
  WorkflowAgentRunner, 
  createWorkflowAgentRunner,
  type AgentRole 
} from '../AgentRunner.js';
import { type AgentGateRunner, createAgentGateRunner } from '../gates/AgentGateRunner.js';
import type { 
  WorkflowDefinition, 
  WorkflowInstance, 
  GateDefinition, 
  GateResult,
  SimpleGateDefinition,
  WorkflowState 
} from '../types.js';
import { WorkflowEngine, type WorkflowEngineConfig, requiresTransitionEvidence } from '../WorkflowEngine.js';

/**
 * AgentWorkflowEngine configuration
 */
export interface AgentWorkflowEngineConfig extends WorkflowEngineConfig {
  agentRunner?: WorkflowAgentRunner;
  defaultAgentRole?: AgentRole;
}

/**
 * AgentWorkflowEngine - Workflow engine with Agent system integration
 * Extends WorkflowEngine to support agent-based gate execution
 */
export class AgentWorkflowEngine extends WorkflowEngine {
  private agentRunner: WorkflowAgentRunner;
  private defaultAgentRole: AgentRole;

  /**
   * Create a new AgentWorkflowEngine
   */
  constructor(config?: AgentWorkflowEngineConfig) {
    super(config);
    this.agentRunner = config?.agentRunner ?? createWorkflowAgentRunner();
    this.defaultAgentRole = config?.defaultAgentRole ?? 'general';
  }

  /**
   * Get the agent runner instance
   */
  getAgentRunner(): WorkflowAgentRunner {
    return this.agentRunner;
  }

  /**
   * Set the agent runner instance
   */
  setAgentRunner(agentRunner: WorkflowAgentRunner): void {
    this.agentRunner = agentRunner;
  }

  /**
   * Get the default agent role
   */
  getDefaultAgentRole(): AgentRole {
    return this.defaultAgentRole;
  }

  /**
   * Set the default agent role
   */
  setDefaultAgentRole(role: AgentRole): void {
    this.defaultAgentRole = role;
  }

  /**
   * Execute a single gate with Agent system integration
   * Overrides parent method to support agent-based gates
   */
  override async executeGate(gate: GateDefinition, state?: WorkflowState): Promise<GateResult> {
    // Check if this state requires agent execution
    if (state && this.shouldUseAgentForState(state)) {
      return this.executeAgentGate(gate as SimpleGateDefinition, state);
    }

    // Fall back to parent implementation for non-agent gates
    return super.executeGate(gate);
  }

  /**
   * Determine if a state should use agent execution
   */
  private shouldUseAgentForState(state: WorkflowState): boolean {
    // Check if state has an agent specified
    if (state.agent && state.agent !== 'none') {
      return true;
    }

    // Check if state has skills that require agents
    if (state.skills && state.skills.length > 0) {
      return true;
    }

    return false;
  }

  /**
   * Execute a gate using the Agent system
   */
  private async executeAgentGate(gate: SimpleGateDefinition, state: WorkflowState): Promise<GateResult> {
    // Determine agent role
    const agentRole = this.determineAgentRoleForState(state);

    // Create agent gate runner
    const agentGateRunner = createAgentGateRunner(
      gate,
      this.agentRunner,
      agentRole,
      { state }
    );

    // Get current instance context
    const instance = this.getCurrentInstance();
    const definition = this.getCurrentWorkflow();

    if (!instance || !definition) {
      throw new Error('No active workflow instance or definition found');
    }

    const context = {
      instance,
      definition,
    };

    // Execute agent gate
    return agentGateRunner.check(context);
  }

  /**
   * Determine agent role for a state
   */
  private determineAgentRoleForState(state: WorkflowState): AgentRole {
    // Use state's agent field if specified
    if (state.agent && state.agent !== 'none') {
      return state.agent as AgentRole;
    }

    // Try to determine from state name
    const stateName = this.getStateName(state);
    if (stateName) {
      return WorkflowAgentRunner.determineAgentRole(stateName);
    }

    // Fall back to default
    return this.defaultAgentRole;
  }

  /**
   * Get state name from workflow definition
   */
  private getStateName(state: WorkflowState): string | undefined {
    const definition = this.getCurrentWorkflow();
    if (!definition) {
      return undefined;
    }

    // Find the state in the workflow definition
    for (const [name, stateDef] of Object.entries(definition.stateMachine.states)) {
      if (stateDef === state) {
        return name;
      }
    }

    return undefined;
  }

  /**
   * Get the current workflow instance (helper method)
   */
  private getCurrentInstance(): WorkflowInstance | undefined {
    // This is a simplified implementation
    // In a real implementation, you would track the current instance
    const instances = this.getAllInstances();
    return instances.length > 0 ? instances[0] : undefined;
  }

  /**
   * Get the current workflow definition (helper method)
   */
  private getCurrentWorkflow(): WorkflowDefinition | undefined {
    const instance = this.getCurrentInstance();
    if (!instance) {
      return undefined;
    }
    return this.getWorkflow(instance.workflowId);
  }

  /**
   * Create a specialized gate runner for agent-based gates
   * This can be used by external code to create agent gate runners
   */
  createAgentGateRunner(
    gate: SimpleGateDefinition,
    agentRole?: AgentRole,
    context?: Record<string, unknown>
  ): AgentGateRunner {
    return createAgentGateRunner(
      gate,
      this.agentRunner,
      agentRole ?? this.defaultAgentRole,
      context
    );
  }

  /**
   * Execute workflow with enhanced agent integration
   * Overrides parent method to use agent-based gate execution
   * v1.1: Evidence prerequisites enforced for CRITICAL_STATES, matching parent WorkflowEngine.execute()
   */
  override async execute(instanceId: string, options?: { workItemDir?: string }): Promise<WorkflowInstance> {
    const instance = this.getInstance(instanceId);
    if (!instance) {
      throw new Error(`Workflow instance not found: ${instanceId}`);
    }

    const definition = this.getWorkflow(instance.workflowId);
    if (!definition) {
      throw new Error(`Workflow definition not found: ${instance.workflowId}`);
    }

    // Update status to running
    instance.status = 'running';
    instance.updatedAt = new Date();

    // Emit workflow started event
    this.emitEvent({
      type: 'workflow.started',
      instanceId: instance.id,
      timestamp: new Date(),
      data: { currentState: instance.currentState },
    });

    // Execute until terminal state or error
    while (instance.status === 'running') {
      const currentStateName = instance.currentState;
      const currentStateDef = definition.stateMachine.states[currentStateName];

      if (!currentStateDef) {
        throw new Error(`State not found: ${currentStateName}`);
      }

      // Publish gate started event
      const eventPublisher = this.getEventPublisher();
      if (eventPublisher) {
        eventPublisher.publishGateStarted(
          instance,
          currentStateName,
          currentStateDef.gate.id,
          currentStateDef.gate.type
        );
      }

      // Execute the gate with agent integration
      const gateResult = await this.executeGate(currentStateDef.gate, currentStateDef);

      // Publish gate completed event
      if (eventPublisher) {
        eventPublisher.publishGateCompleted(
          instance,
          currentStateName,
          currentStateDef.gate.id,
          currentStateDef.gate.type,
          gateResult
        );
      }

      // Emit gate execution event
      this.emitEvent({
        type: 'workflow.gate_executed',
        instanceId: instance.id,
        timestamp: new Date(),
        data: { state: currentStateName, gateResult },
      });

      // Determine next state
      const nextState = this.determineNextState(currentStateDef, gateResult);

      if (!nextState) {
        // No more transitions - workflow completed
        instance.status = 'completed';
        instance.updatedAt = new Date();

        // Publish workflow completed event
        if (eventPublisher) {
          eventPublisher.publishWorkflowCompleted(instance, currentStateName);
        }

        this.emitEvent({
          type: 'workflow.completed',
          instanceId: instance.id,
          timestamp: new Date(),
          data: { finalState: currentStateName },
        });
        break;
      }

      // Transition to next state
      const oldState = currentStateName;

      // v1.1: Enforce evidence prerequisites — MANDATORY for critical states
      const wdir = options?.workItemDir;
      if (requiresTransitionEvidence(nextState)) {
        if (!wdir) {
          throw new Error(`Cannot transition to '${nextState}': workItemDir is required for critical state transitions`);
        }
        // v1.1: Verify workItemDir belongs to this instance (prevent cross-WI evidence pollution)
        this.verifyWorkItemDirOwnership(instance.id, wdir);
        await this.enforceTransitionEvidence(nextState, wdir);
      } else if (wdir) {
        this.verifyWorkItemDirOwnership(instance.id, wdir);
        await this.enforceTransitionEvidence(nextState, wdir);
      }

      instance.currentState = nextState;
      instance.updatedAt = new Date();

      // Publish state changed event
      if (eventPublisher) {
        eventPublisher.publishStateChanged(instance, oldState, nextState, gateResult.passed);
      }

      this.emitEvent({
        type: 'workflow.state_changed',
        instanceId: instance.id,
        timestamp: new Date(),
        data: { from: oldState, to: nextState },
      });
    }

    return instance;
  }

  /**
   * Determine the next state based on gate result
   * v1.1 strict: matches parent WorkflowEngine semantics
   * - only passed=true counts (not_enabled / blocked / waived are NOT pass)
   * - string next + gate failed → throws (unconsumed gate result)
   */
  protected override determineNextState(
    stateDef: { next?: string | Record<string, string>; gate?: unknown },
    gateResult: GateResult
  ): string | null {
    if (!stateDef.next) {
      return null;
    }

    const hasGate = stateDef.gate != null;
    // v1.1 strict: only passed=true counts. not_enabled / blocked / waived are NOT pass.
    const gateOk = gateResult.passed === true;

    if (typeof stateDef.next === 'string') {
      if (hasGate && !gateOk) {
        throw new Error(`Gate '${(stateDef.gate as { id?: string }).id ?? 'unknown'}' result: passed=${gateResult.passed}, status=${gateResult.status ?? 'undefined'} — gate result is unconsumed (string next). Use { pass, fail } branching or ensure gate passes.`);
      }
      return stateDef.next;
    }

    if (gateOk && stateDef.next['pass']) {
      return stateDef.next['pass'];
    }
    if (!gateResult.passed && stateDef.next['fail']) {
      return stateDef.next['fail'];
    }

    return null;
  }
}

/**
 * Create a new AgentWorkflowEngine
 */
export function createAgentWorkflowEngine(config?: AgentWorkflowEngineConfig): AgentWorkflowEngine {
  return new AgentWorkflowEngine(config);
}

/**
 * Workflow Loader
 * High-level API for loading and managing workflow definitions
 * Integrates with WorkflowEngine for seamless workflow loading
 */

import * as fs from 'fs/promises';
import * as path from 'path';

import { type ValidationResult , WorkflowDefinitionLoader } from '../loaders/WorkflowDefinitionLoader.js';
import type { WorkflowDefinition } from '../types.js';

/**
 * Workflow Loader
 * Provides high-level API for loading workflow definitions with schema version support
 */
export class WorkflowLoader {
  private definitionLoader: WorkflowDefinitionLoader;
  private loadedDefinitions: Map<string, WorkflowDefinition> = new Map();

  constructor() {
    this.definitionLoader = new WorkflowDefinitionLoader();
  }

  /**
   * Load a workflow definition from a file
   * Rejects unsupported or missing schema; never converts persisted inputs.
   * @param filePath Path to the workflow definition file
   * @returns The loaded workflow definition
   * @throws Error if file cannot be read, parsed, or validated
   */
  async loadFromFile(filePath: string): Promise<WorkflowDefinition> {
    try {
      const definition = await this.definitionLoader.loadFromFile(filePath);
      this.loadedDefinitions.set(definition.id, definition);
      return definition;
    } catch (error) {
      if (error instanceof Error) {
        throw new Error(`Failed to load workflow from file ${filePath}: ${error.message}`);
      }
      throw error;
    }
  }

  /**
   * Load a workflow definition from a JSON string
   * @param jsonString JSON string containing the workflow definition
   * @returns The loaded workflow definition
   * @throws Error if JSON is invalid or validation fails
   */
  loadFromJSON(jsonString: string): WorkflowDefinition {
    try {
      const definition = this.definitionLoader.loadFromJSON(jsonString);
      this.loadedDefinitions.set(definition.id, definition);
      return definition;
    } catch (error) {
      if (error instanceof Error) {
        throw new Error(`Failed to load workflow from JSON: ${error.message}`);
      }
      throw error;
    }
  }

  /**
   * Load a workflow definition from a YAML string
   * @param yamlString YAML string containing the workflow definition
   * @returns The loaded workflow definition
   * @throws Error if YAML is invalid or validation fails
   */
  loadFromYAML(yamlString: string): WorkflowDefinition {
    try {
      const definition = this.definitionLoader.loadFromYAML(yamlString);
      this.loadedDefinitions.set(definition.id, definition);
      return definition;
    } catch (error) {
      if (error instanceof Error) {
        throw new Error(`Failed to load workflow from YAML: ${error.message}`);
      }
      throw error;
    }
  }

  /**
   * Load a workflow definition from an object
   * @param obj Object containing the workflow definition
   * @returns The loaded workflow definition
   * @throws Error if object is invalid or validation fails
   */
  loadFromObject(obj: unknown): WorkflowDefinition {
    try {
      const definition = this.definitionLoader.loadFromObject(obj);
      this.loadedDefinitions.set(definition.id, definition);
      return definition;
    } catch (error) {
      if (error instanceof Error) {
        throw new Error(`Failed to load workflow from object: ${error.message}`);
      }
      throw error;
    }
  }

  /**
   * Load a workflow definition from a directory
   * Loads all JSON/YAML files in the directory
   * @param dirPath Path to the directory containing workflow definitions
   * @returns Array of loaded workflow definitions
   * @throws Error if directory cannot be read
   */
  async loadFromDirectory(dirPath: string): Promise<WorkflowDefinition[]> {
    try {
      const files = (await fs.readdir(dirPath)).sort().filter(file => ['.json', '.yaml', '.yml'].includes(path.extname(file).toLowerCase()));
      // Validate the complete set before publishing any new cache entries.
      const definitions = await Promise.all(files.map(file => this.definitionLoader.loadFromFile(path.join(dirPath, file))));
      for (const definition of definitions) this.loadedDefinitions.set(definition.id, definition);

      return definitions;
    } catch (error) {
      if (error instanceof Error) {
        throw new Error(`Failed to load workflows from directory ${dirPath}: ${error.message}`);
      }
      throw error;
    }
  }

  /**
   * Validate a workflow definition
   * @param definition The workflow definition to validate
   * @returns Validation result with errors if any
   */
  validate(definition: WorkflowDefinition): ValidationResult {
    return this.definitionLoader.validate(definition);
  }

  /**
   * Validate a workflow definition and throw if invalid
   * @param definition The workflow definition to validate
   * @throws Error if validation fails
   */
  validateOrThrow(definition: WorkflowDefinition): void {
    const result = this.validate(definition);
    if (!result.valid) {
      const errorMessages = result.errors.map(e => `${e.field}: ${e.message}`).join('\n');
      throw new Error(`Workflow definition validation failed:\n${errorMessages}`);
    }
  }

  /**
   * Get a previously loaded workflow definition by ID
   * @param workflowId The workflow ID
   * @returns The workflow definition or undefined if not found
   */
  getLoadedDefinition(workflowId: string): WorkflowDefinition | undefined {
    return this.loadedDefinitions.get(workflowId);
  }

  /**
   * Get all loaded workflow definitions
   * @returns Array of all loaded workflow definitions
   */
  getAllLoadedDefinitions(): WorkflowDefinition[] {
    return Array.from(this.loadedDefinitions.values());
  }

  /**
   * Clear all loaded workflow definitions
   */
  clearLoadedDefinitions(): void {
    this.loadedDefinitions.clear();
  }

  /**
   * Check if a workflow definition is loaded
   * @param workflowId The workflow ID
   * @returns true if the workflow is loaded, false otherwise
   */
  isLoaded(workflowId: string): boolean {
    return this.loadedDefinitions.has(workflowId);
  }

  /**
   * Get the underlying WorkflowDefinitionLoader
   * For advanced use cases where direct access to the loader is needed
   */
  getDefinitionLoader(): WorkflowDefinitionLoader {
    return this.definitionLoader;
  }

  // ── V6 Daemon Integration Methods ──────────────────────────────────

  /** Default builtin workflows directory */
  static BUILTIN_DIR = 'configs/workflows/builtin';

  /**
   * Load the current release builtin workflow from the default directory
   * Called by Daemon during startup
   * @param builtinDir Optional override for builtin directory path
   * @returns Array of loaded workflow definitions
   */
  async loadBuiltinWorkflows(builtinDir?: string): Promise<WorkflowDefinition[]> {
    const dir = builtinDir || WorkflowLoader.BUILTIN_DIR;
    const definition = await this.definitionLoader.loadFromFile(path.join(dir, 'feature_spec.json'));
    if (definition.id !== 'feature_spec') throw new Error('BUILTIN_WORKFLOW_IDENTITY_MISMATCH');
    this.loadedDefinitions.set(definition.id, definition);
    return [definition];
  }

  /**
   * Hot-reload all workflow definitions from a directory
   * Clears existing definitions and reloads from disk
   * @param dirPath Optional directory path (defaults to builtin dir)
   * @returns Number of workflows loaded
   */
  async hotReload(dirPath?: string): Promise<number> {
    const dir = dirPath || WorkflowLoader.BUILTIN_DIR;
    const definitions = await this.loadBuiltinWorkflows(dir);
    this.clearLoadedDefinitions();
    for (const definition of definitions) this.loadedDefinitions.set(definition.id, definition);
    return definitions.length;
  }

  /**
   * Get a loaded workflow definition by ID (alias for getLoadedDefinition)
   * Matches the WorkflowEngine.getWorkflow() interface
   */
  getWorkflow(id: string): WorkflowDefinition | undefined {
    return this.loadedDefinitions.get(id);
  }

  /**
   * List all registered workflow IDs
   */
  listWorkflowIds(): string[] {
    return Array.from(this.loadedDefinitions.keys());
  }

  /**
   * Register a workflow definition directly (for runtime registration)
   * @param definition The workflow definition to register
   */
  register(definition: WorkflowDefinition): void {
    const accepted = this.definitionLoader.loadFromObject(definition);
    this.loadedDefinitions.set(accepted.id, accepted);
  }

  /**
   * Unregister a workflow definition
   * @param workflowId The workflow ID to unregister
   * @returns true if the workflow was found and removed
   */
  unregister(workflowId: string): boolean {
    return this.loadedDefinitions.delete(workflowId);
  }
}

