/**
 * Basic Gate Types Module
 * Implements RequirementsGate, DesignGate, TasksGate, and VerificationGate
 */

import type { GateResult, SimpleGateDefinition } from '../types.js';

const CURRENT_SCHEMA_VERSION = '1.0';

/**
 * Create a GateResult with schema_version
 */
function createGateResult(result: Omit<GateResult, 'schema_version'>): GateResult {
  return { schema_version: CURRENT_SCHEMA_VERSION, ...result };
}

/**
 * Base class for all basic Gate types
 */
export abstract class BaseGate {
  protected id: string;
  protected name: string;
  protected config: Record<string, unknown>;

  /**
   * Create a new BaseGate
   */
  constructor(id: string, name: string, config: Record<string, unknown> = {}) {
    this.id = id;
    this.name = name;
    this.config = config;
  }

  /**
   * Get the gate ID
   */
  getId(): string {
    return this.id;
  }

  /**
   * Get the gate name
   */
  getName(): string {
    return this.name;
  }

  /**
   * Get the gate configuration
   */
  getConfig(): Record<string, unknown> {
    return this.config;
  }

  /**
   * Execute the gate check
   * Must be implemented by subclasses
   */
  abstract check(): Promise<GateResult> | GateResult;

  /**
   * Get gate definition for serialization
   */
  abstract toGateDefinition(): SimpleGateDefinition;
}

/**
 * RequirementsGate - Validates requirements completeness
 * Checks if all required sections are present and properly formatted
 */
export class RequirementsGate extends BaseGate {
  private requiredSections: string[];
  private minLength: number;

  /**
   * Create a new RequirementsGate
   */
  constructor(
    id: string = 'requirements-gate',
    config: {
      requiredSections?: string[];
      minLength?: number;
    } = {}
  ) {
    super(id, 'Requirements Gate', config);
    this.requiredSections = config.requiredSections ?? [
      'Introduction',
      'Requirements',
      'Acceptance Criteria',
    ];
    this.minLength = config.minLength ?? 100;
  }

  /**
   * Check requirements completeness
   * Accepts requirements content directly or via config
   */
  check(): GateResult {
    const requirementsContent = this.config.content as string | undefined;

    if (!requirementsContent) {
      // No content provided - check if content is expected to be loaded from elsewhere
      if (this.config.requireContent === false) {
        // Content not required for this gate
        return createGateResult({
          passed: true,
          reason: 'Requirements gate check passed (no content required)',
          details: { gateId: this.id },
        });
      }

      return createGateResult({
        passed: false,
        reason: 'No requirements content provided',
        details: { gateId: this.id },
      });
    }

    // Check required sections
    const missingSections: string[] = [];
    for (const section of this.requiredSections) {
      if (!requirementsContent.toLowerCase().includes(section.toLowerCase())) {
        missingSections.push(section);
      }
    }

    if (missingSections.length > 0) {
      return createGateResult({
        passed: false,
        reason: `Missing required sections: ${missingSections.join(', ')}`,
        details: {
          gateId: this.id,
          missingSections,
          requiredSections: this.requiredSections,
        },
      });
    }

    // Check minimum length
    if (requirementsContent.length < this.minLength) {
      return createGateResult({
        passed: false,
        reason: `Requirements content too short (${requirementsContent.length} chars, minimum ${this.minLength})`,
        details: {
          gateId: this.id,
          contentLength: requirementsContent.length,
          minLength: this.minLength,
        },
      });
    }

    return createGateResult({
      passed: true,
      reason: 'All required sections present and content meets minimum length',
      details: {
        gateId: this.id,
        contentLength: requirementsContent.length,
        sectionsFound: this.requiredSections.length,
      },
    });
  }

  /**
   * Convert to GateDefinition
   */
  toGateDefinition(): SimpleGateDefinition {
    return {
      schema_version: CURRENT_SCHEMA_VERSION,
      type: 'simple',
      id: this.id,
      name: this.name,
    };
  }
}

/**
 * DesignGate - Validates design completeness
 * Checks if design document has all required components
 */
export class DesignGate extends BaseGate {
  private requiredComponents: string[];

  /**
   * Create a new DesignGate
   */
  constructor(
    id: string = 'design-gate',
    config: {
      requiredComponents?: string[];
    } = {}
  ) {
    super(id, 'Design Gate', config);
    this.requiredComponents = config.requiredComponents ?? [
      'Architecture',
      'Implementation Details',
      'Data Models',
    ];
  }

  /**
   * Check design completeness
   */
  check(): GateResult {
    const designContent = this.config.content as string | undefined;

    if (!designContent) {
      if (this.config.requireContent === false) {
        return createGateResult({
          passed: true,
          reason: 'Design gate check passed (no content required)',
          details: { gateId: this.id },
        });
      }

      return createGateResult({
        passed: false,
        reason: 'No design content provided',
        details: { gateId: this.id },
      });
    }

    // Check required components
    const missingComponents: string[] = [];
    for (const component of this.requiredComponents) {
      if (!designContent.toLowerCase().includes(component.toLowerCase())) {
        missingComponents.push(component);
      }
    }

    if (missingComponents.length > 0) {
      return createGateResult({
        passed: false,
        reason: `Missing required design components: ${missingComponents.join(', ')}`,
        details: {
          gateId: this.id,
          missingComponents,
          requiredComponents: this.requiredComponents,
        },
      });
    }

    return createGateResult({
      passed: true,
      reason: 'All required design components present',
      details: {
        gateId: this.id,
        componentsFound: this.requiredComponents.length,
      },
    });
  }

  /**
   * Convert to GateDefinition
   */
  toGateDefinition(): SimpleGateDefinition {
    return {
      schema_version: CURRENT_SCHEMA_VERSION,
      type: 'simple',
      id: this.id,
      name: this.name,
    };
  }
}

/**
 * TasksGate - Validates tasks completeness
 * Checks if all tasks are defined with proper structure
 */
export class TasksGate extends BaseGate {
  private minTasks: number;
  private requirePhases: boolean;

  /**
   * Create a new TasksGate
   */
  constructor(
    id: string = 'tasks-gate',
    config: {
      minTasks?: number;
      requirePhases?: boolean;
    } = {}
  ) {
    super(id, 'Tasks Gate', config);
    this.minTasks = config.minTasks ?? 1;
    this.requirePhases = config.requirePhases ?? false;
  }

  /**
   * Check tasks completeness
   */
  check(): GateResult {
    const tasksContent = this.config.content as string | undefined;
    const tasksData = this.config.tasks as Array<{ id: string; title: string; subtasks?: Array<{ id: string }> }> | undefined;

    // If tasks are provided as structured data
    if (tasksData) {
      if (tasksData.length < this.minTasks) {
        return createGateResult({
          passed: false,
          reason: `Insufficient tasks (${tasksData.length}, minimum ${this.minTasks})`,
          details: {
            gateId: this.id,
            taskCount: tasksData.length,
            minTasks: this.minTasks,
          },
        });
      }

      // Check for empty task titles
      const emptyTasks = tasksData.filter(t => !t.title || t.title.trim() === '');
      if (emptyTasks.length > 0) {
        return createGateResult({
          passed: false,
          reason: `Found ${emptyTasks.length} tasks with empty titles`,
          details: {
            gateId: this.id,
            emptyTaskIds: emptyTasks.map(t => t.id),
          },
        });
      }

      // Check if phases are required
      if (this.requirePhases) {
        const tasksWithSubtasks = tasksData.filter(t => t.subtasks && t.subtasks.length > 0);
        if (tasksWithSubtasks.length === 0) {
          return createGateResult({
            passed: false,
            reason: 'Tasks require phases (subtasks) but none found',
            details: {
              gateId: this.id,
              requirePhases: true,
            },
          });
        }
      }

      return createGateResult({
        passed: true,
        reason: `All ${tasksData.length} tasks are valid`,
        details: {
          gateId: this.id,
          taskCount: tasksData.length,
        },
      });
    }

    // If content is provided as text
    if (tasksContent) {
      // Basic check: look for task markers like "- [ ]" or "1."
      const taskMarkers = tasksContent.match(/^[-*]\s*\[\s*\]|^\\d+\\./m);
      const taskCount = taskMarkers?.length ?? 0;

      if (taskCount < this.minTasks) {
        return createGateResult({
          passed: false,
          reason: `Insufficient tasks found in content (${taskCount}, minimum ${this.minTasks})`,
          details: {
            gateId: this.id,
            taskCount,
            minTasks: this.minTasks,
          },
        });
      }

      return createGateResult({
        passed: true,
        reason: `Found ${taskCount} tasks in content`,
        details: {
          gateId: this.id,
          taskCount,
        },
      });
    }

    // No content provided
    if (this.config.requireContent === false) {
      return createGateResult({
        passed: true,
        reason: 'Tasks gate check passed (no content required)',
        details: { gateId: this.id },
      });
    }

    return createGateResult({
      passed: false,
      reason: 'No tasks content provided',
      details: { gateId: this.id },
    });
  }

  /**
   * Convert to GateDefinition
   */
  toGateDefinition(): SimpleGateDefinition {
    return {
      schema_version: CURRENT_SCHEMA_VERSION,
      type: 'simple',
      id: this.id,
      name: this.name,
    };
  }
}

/**
 * VerificationGate - Validates verification criteria
 * Checks if verification tests and checks are in place
 */
export class VerificationGate extends BaseGate {
  private requireTests: boolean;
  private minTests: number;

  /**
   * Create a new VerificationGate
   */
  constructor(
    id: string = 'verification-gate',
    config: {
      requireTests?: boolean;
      minTests?: number;
    } = {}
  ) {
    super(id, 'Verification Gate', config);
    this.requireTests = config.requireTests ?? true;
    this.minTests = config.minTests ?? 1;
  }

  /**
   * Check verification completeness
   */
  check(): GateResult {
    const verificationContent = this.config.content as string | undefined;
    const testData = this.config.testCount as number | undefined;
    const hasUnitTests = this.config.hasUnitTests as boolean | undefined;
    const hasPropertyTests = this.config.hasPropertyTests as boolean | undefined;

    // If test count is provided directly
    if (testData !== undefined) {
      if (this.requireTests && testData < this.minTests) {
        return createGateResult({
          passed: false,
          reason: `Insufficient tests (${testData}, minimum ${this.minTests})`,
          details: {
            gateId: this.id,
            testCount: testData,
            minTests: this.minTests,
          },
        });
      }

      return createGateResult({
        passed: true,
        reason: `Verification complete with ${testData} tests`,
        details: {
          gateId: this.id,
          testCount: testData,
          hasUnitTests,
          hasPropertyTests,
        },
      });
    }

    // If content is provided as text
    if (verificationContent) {
      // Look for test-related keywords
      const testKeywords = ['test', 'verify', 'check', 'validate', 'spec'];
      const foundKeywords = testKeywords.filter(keyword =>
        verificationContent.toLowerCase().includes(keyword)
      );

      if (foundKeywords.length === 0) {
        return createGateResult({
          passed: false,
          reason: 'No verification criteria found in content',
          details: {
            gateId: this.id,
          },
        });
      }

      return createGateResult({
        passed: true,
        reason: `Verification criteria found: ${foundKeywords.join(', ')}`,
        details: {
          gateId: this.id,
          keywordsFound: foundKeywords,
        },
      });
    }

    // No content provided
    if (this.config.requireContent === false) {
      return createGateResult({
        passed: true,
        reason: 'Verification gate check passed (no content required)',
        details: { gateId: this.id },
      });
    }

    return createGateResult({
      passed: false,
      reason: 'No verification content provided',
      details: { gateId: this.id },
    });
  }

  /**
   * Convert to GateDefinition
   */
  toGateDefinition(): SimpleGateDefinition {
    return {
      schema_version: CURRENT_SCHEMA_VERSION,
      type: 'simple',
      id: this.id,
      name: this.name,
    };
  }
}

/**
 * Factory function to create basic gate instances
 */
export function createBasicGate(
  type: 'requirements' | 'design' | 'tasks' | 'verification',
  config?: Record<string, unknown>
): BaseGate {
  switch (type) {
    case 'requirements':
      return new RequirementsGate(config?.id as string, config);
    case 'design':
      return new DesignGate(config?.id as string, config);
    case 'tasks':
      return new TasksGate(config?.id as string, config);
    case 'verification':
      return new VerificationGate(config?.id as string, config);
    default:
      throw new Error(`Unknown gate type: ${type}`);
  }
}

/**
 * CompositeGate Serializer Module
 * Handles serialization and deserialization of CompositeGate definitions
 * 
 * Validates: Requirements 3.1 - compositeGate 序列化/反序列化
 */

import type {
  GateDefinition,
  SimpleGateDefinition,
  CompositeGateDefinition,
  CompositeGateMode,
  FailPolicy,
} from '../types.js';

/**
 * Validation errors for CompositeGate
 */
export interface ValidationError {
  field: string;
  message: string;
}

/**
 * Serialized CompositeGate structure (JSON compatible)
 */
export interface SerializedCompositeGate {
  schema_version: '1.0';
  type: 'composite';
  id: string;
  name: string;
  mode: CompositeGateMode;
  failPolicy: FailPolicy;
  children: SerializedGateDefinition[];
}

/**
 * Union type for serialized gate definitions
 */
export type SerializedGateDefinition = 
  | SerializedSimpleGate
  | SerializedCompositeGate;

export interface SerializedSimpleGate {
  schema_version: '1.0';
  type: 'simple';
  id: string;
  name: string;
  checkFn?: string; // Serialized as function reference name
}

/**
 * Result of validation
 */
export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

/**
 * CompositeGateSerializer class
 * Provides serialization and deserialization for CompositeGate definitions
 */
export class CompositeGateSerializer {
  /**
   * Serialize a CompositeGateDefinition to JSON-compatible object
   * @param gate The CompositeGateDefinition to serialize
   * @returns Serialized CompositeGate
   */
  static serialize(gate: CompositeGateDefinition): SerializedCompositeGate {
    if (gate.type !== 'composite') {
      throw new Error('Cannot serialize non-composite gate as CompositeGate');
    }
    if (gate.schema_version !== '1.0') throw new Error('SERIALIZED_GATE_SCHEMA_UNSUPPORTED: expected 1.0');

    const serialized: SerializedCompositeGate = {
      schema_version: gate.schema_version,
      type: 'composite',
      id: gate.id,
      name: gate.name,
      mode: gate.mode,
      failPolicy: gate.failPolicy,
      children: gate.children.map(child => this.serializeGateDefinition(child)),
    };

    return serialized;
  }

  /**
   * Serialize any GateDefinition to its serialized form
   */
  static serializeGateDefinition(gate: GateDefinition): SerializedGateDefinition {
    if (gate.type === 'simple') {
      return this.serializeSimpleGate(gate);
    } else {
      return this.serialize(gate);
    }
  }

  /**
   * Serialize a SimpleGateDefinition
   */
  static serializeSimpleGate(gate: SimpleGateDefinition): SerializedSimpleGate {
    if (gate.type !== 'simple' || gate.schema_version !== '1.0') throw new Error('SERIALIZED_GATE_SCHEMA_UNSUPPORTED: expected simple Gate 1.0');
    return {
      schema_version: gate.schema_version,
      type: 'simple',
      id: gate.id,
      name: gate.name,
      // Note: checkFn cannot be serialized directly, serialize as reference name if available
      ...(gate.checkFn && { checkFn: 'checkFn' }),
    };
  }

  /**
   * Deserialize a SerializedCompositeGate back to CompositeGateDefinition
   * @param data The serialized data
   * @param context Optional context for resolving function references
   * @returns CompositeGateDefinition
   */
  static deserialize(
    data: SerializedCompositeGate,
    context?: { checkFnMap?: Record<string, () => Promise<any> | any> }
  ): CompositeGateDefinition {
    // Validate the serialized data
    const validationResult = this.validateSerialized(data);
    if (!validationResult.valid) {
      const errorMessages = validationResult.errors
        .map(e => `${e.field}: ${e.message}`)
        .join(', ');
      throw new Error(`Invalid CompositeGate data: ${errorMessages}`);
    }

    const compositeGate: CompositeGateDefinition = {
      schema_version: data.schema_version,
      type: 'composite',
      id: data.id,
      name: data.name,
      mode: data.mode,
      failPolicy: data.failPolicy,
      children: data.children.map(child => 
        this.deserializeGateDefinition(child, context)
      ),
    };

    return compositeGate;
  }

  /**
   * Deserialize any SerializedGateDefinition back to GateDefinition
   */
  static deserializeGateDefinition(
    data: SerializedGateDefinition,
    context?: { checkFnMap?: Record<string, () => Promise<any> | any> }
  ): GateDefinition {
    if (data.type === 'simple') {
      return this.deserializeSimpleGate(data, context);
    } else {
      return this.deserialize(data, context);
    }
  }

  /**
   * Deserialize a SerializedSimpleGate back to SimpleGateDefinition
   */
  static deserializeSimpleGate(
    data: SerializedSimpleGate,
    context?: { checkFnMap?: Record<string, () => Promise<any> | any> }
  ): SimpleGateDefinition {
    const validation = this.validateSerializedGate(data);
    if (!validation.valid || data.type !== 'simple') throw new Error('SERIALIZED_GATE_SCHEMA_INVALID');
    const gate: SimpleGateDefinition = {
      schema_version: data.schema_version,
      type: 'simple',
      id: data.id,
      name: data.name,
    };

    // Restore checkFn if reference name provided and context available
    if (data.checkFn && context?.checkFnMap?.[data.checkFn]) {
      gate.checkFn = context.checkFnMap[data.checkFn];
    }

    return gate;
  }

  /**
   * Validate serialized CompositeGate data
   */
  static validateSerialized(data: unknown): ValidationResult {
    const errors: ValidationError[] = [];

    if (!data || typeof data !== 'object') {
      errors.push({ field: 'root', message: 'Data must be an object' });
      return { valid: false, errors };
    }

    const obj = data as Record<string, unknown>;

    // Check schema_version
    if (!obj.schema_version) {
      errors.push({ field: 'schema_version', message: 'Missing schema_version' });
    } else if (obj.schema_version !== '1.0') {
      errors.push({ field: 'schema_version', message: `Unsupported schema version: ${obj.schema_version}` });
    }

    // Check type
    if (obj.type !== 'composite') {
      errors.push({ field: 'type', message: 'Type must be "composite"' });
    }

    // Check id
    if (!obj.id || typeof obj.id !== 'string') {
      errors.push({ field: 'id', message: 'id must be a non-empty string' });
    }

    // Check name
    if (!obj.name || typeof obj.name !== 'string') {
      errors.push({ field: 'name', message: 'name must be a non-empty string' });
    }

    // Check mode
    const validModes: CompositeGateMode[] = ['sequential', 'parallel'];
    if (!obj.mode || !validModes.includes(obj.mode as CompositeGateMode)) {
      errors.push({ 
        field: 'mode', 
        message: `mode must be one of: ${validModes.join(', ')}` 
      });
    }

    // Check failPolicy
    const validFailPolicies: FailPolicy[] = ['fail_fast', 'collect_all'];
    if (!obj.failPolicy || !validFailPolicies.includes(obj.failPolicy as FailPolicy)) {
      errors.push({ 
        field: 'failPolicy', 
        message: `failPolicy must be one of: ${validFailPolicies.join(', ')}` 
      });
    }

    // Check children
    if (!Array.isArray(obj.children)) {
      errors.push({ field: 'children', message: 'children must be an array' });
    } else {
      obj.children.forEach((child, index) => {
        const childErrors = this.validateSerializedGate(child);
        childErrors.errors.forEach(err => {
          errors.push({ 
            field: `children[${index}].${err.field}`, 
            message: err.message 
          });
        });
      });
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Validate a serialized gate definition
   */
  static validateSerializedGate(data: unknown): ValidationResult {
    const errors: ValidationError[] = [];

    if (!data || typeof data !== 'object') {
      errors.push({ field: 'root', message: 'Data must be an object' });
      return { valid: false, errors };
    }

    const obj = data as Record<string, unknown>;

    // Check schema_version
    if (!obj.schema_version) {
      errors.push({ field: 'schema_version', message: 'Missing schema_version' });
    } else if (obj.schema_version !== '1.0') {
      errors.push({ field: 'schema_version', message: 'Unsupported serialized Gate schema: expected 1.0' });
    }

    // Check type
    if (!obj.type || !['simple', 'composite'].includes(obj.type as string)) {
      errors.push({ field: 'type', message: 'type must be "simple" or "composite"' });
    }

    // Check id
    if (!obj.id || typeof obj.id !== 'string') {
      errors.push({ field: 'id', message: 'id must be a non-empty string' });
    }

    // Check name
    if (!obj.name || typeof obj.name !== 'string') {
      errors.push({ field: 'name', message: 'name must be a non-empty string' });
    }

    // For composite type, validate children
    if (obj.type === 'composite') {
      if (!Array.isArray(obj.children)) {
        errors.push({ field: 'children', message: 'children must be an array for composite gates' });
      }
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Convert a CompositeGate to JSON string
   */
  static toJSON(gate: CompositeGateDefinition): string {
    return JSON.stringify(this.serialize(gate), null, 2);
  }

  /**
   * Parse a JSON string to CompositeGateDefinition
   */
  static fromJSON(
    json: string,
    context?: { checkFnMap?: Record<string, () => Promise<any> | any> }
  ): CompositeGateDefinition {
    try {
      const data = JSON.parse(json) as SerializedCompositeGate;
      return this.deserialize(data, context);
    } catch (error) {
      if (error instanceof SyntaxError) {
        throw new Error(`Invalid JSON: ${error.message}`);
      }
      throw error;
    }
  }
}

/**
 * Helper function to validate a CompositeGateDefinition
 */
export function validateCompositeGate(gate: CompositeGateDefinition): ValidationResult {
  const errors: ValidationError[] = [];

  // Check schema_version
  if (!gate.schema_version) {
    errors.push({ field: 'schema_version', message: 'Missing schema_version' });
  }

  // Check id
  if (!gate.id || typeof gate.id !== 'string') {
    errors.push({ field: 'id', message: 'id must be a non-empty string' });
  }

  // Check name
  if (!gate.name || typeof gate.name !== 'string') {
    errors.push({ field: 'name', message: 'name must be a non-empty string' });
  }

  // Check mode
  const validModes: CompositeGateMode[] = ['sequential', 'parallel'];
  if (!gate.mode || !validModes.includes(gate.mode)) {
    errors.push({ 
      field: 'mode', 
      message: `mode must be one of: ${validModes.join(', ')}` 
    });
  }

  // Check failPolicy
  const validFailPolicies: FailPolicy[] = ['fail_fast', 'collect_all'];
  if (!gate.failPolicy || !validFailPolicies.includes(gate.failPolicy)) {
    errors.push({ 
      field: 'failPolicy', 
      message: `failPolicy must be one of: ${validFailPolicies.join(', ')}` 
    });
  }

  // Check children
  if (!Array.isArray(gate.children)) {
    errors.push({ field: 'children', message: 'children must be an array' });
  } else if (gate.children.length === 0) {
    errors.push({ field: 'children', message: 'children cannot be empty' });
  } else {
    gate.children.forEach((child, index) => {
      if (!child.id) {
        errors.push({ field: `children[${index}].id`, message: 'child gate must have id' });
      }
      if (!child.type) {
        errors.push({ field: `children[${index}].type`, message: 'child gate must have type' });
      }
    });
  }

  return { valid: errors.length === 0, errors };
}

