import { SPEC_DIR_NAME } from "@specforge/types/directory-layout";
/**
 * ProtectedFileMatcher.ts — 受保护文件路径匹配器
 *
 * 根据 filePath 判断资源类型（ResourceType）。
 * 路径匹配保持保守：只识别 .specforge/ 下的已知文件名，
 * 不将普通源码文件误判为受保护资源。
 *
 * 无法识别的路径返回 undefined（调用方应视为不受保护 / code_file），
 * 不提升权限。
 */

import type { ResourceType } from '@specforge/types/permissions';

// ---------------------------------------------------------------------------
// 匹配规则
// ---------------------------------------------------------------------------

/**
 * 文件名 → 资源类型映射。
 *
 * 只匹配确切的文件名（basename），不匹配目录前缀。
 * 调用方负责确保 filePath 是文件路径而非目录路径。
 */
const FILE_NAME_TO_RESOURCE_TYPE: ReadonlyMap<string, ResourceType> = new Map([
  // spec_file
  ['requirements.md', 'spec_file'],
  ['design.md', 'spec_file'],
  ['tasks.md', 'spec_file'],

  // gate_file
  ['gate_summary.md', 'gate_file'],
  ['gate_result.md', 'gate_file'],

  // decision_file
  ['user_decision.json', 'decision_file'],

  // merge_file
  ['merge_report.md', 'merge_file'],

  // evidence_file
  ['verification_report.md', 'evidence_file'],
  ['changed_files_audit.md', 'evidence_file'],
  ['close_gate.md', 'evidence_file'],
  ['close_gate.json', 'evidence_file'],
]);

/**
 * 目录片段 → 资源类型映射。
 *
 * 如果路径包含这些目录片段，即使文件名不在上面映射中，
 * 也可以归入对应资源类型。
 */
const DIR_SEGMENT_TO_RESOURCE_TYPE: ReadonlyMap<string, ResourceType> = new Map([
  // Project module 与 Work Item Candidate 下的 spec 文件
  // 不匹配——由文件名匹配覆盖

  // gates/ 目录下的文件
  ['gates', 'gate_file'],

  // evidence/ 目录下的文件
  ['evidence', 'evidence_file'],
]);

// ---------------------------------------------------------------------------
// extractBasename
// ---------------------------------------------------------------------------

/**
 * 从路径中提取文件名（最后一个路径片段）。
 * 同时处理 / 和 \ 路径分隔符。
 */
function extractBasename(filePath: string): string {
  const normalized = filePath.replace(/\\/g, '/');
  const lastSlash = normalized.lastIndexOf('/');
  return lastSlash >= 0 ? normalized.slice(lastSlash + 1) : normalized;
}

// ---------------------------------------------------------------------------
// ProtectedFileMatcher
// ---------------------------------------------------------------------------

/**
 * 受保护文件路径匹配器。
 *
 * 用法：
 * ```ts
 * const resourceType = ProtectedFileMatcher.match('.specforge/project/modules/CORE/requirements.md');
 * // => 'spec_file'
 *
 * const unknown = ProtectedFileMatcher.match('src/index.ts');
 * // => undefined
 * ```
 */
export const ProtectedFileMatcher = {
  /**
   * 根据文件路径判断资源类型。
   *
   * @param filePath 文件路径（相对项目根或绝对路径均可）
   * @returns ResourceType 或 undefined
   *
   * 匹配策略（按优先级）：
   * 1. 精确文件名匹配（basename）
   * 2. 目录片段匹配（如果路径在 .specforge/ 下）
   * 3. 未识别 → undefined
   */
  match(filePath: string): ResourceType | undefined {
    if (!filePath || typeof filePath !== 'string') {
      return undefined;
    }

    const normalized = filePath.replace(/\\/g, '/');

    // 安全边界：只识别 .specforge/ 下的路径
    // 不将普通源码文件误判
    if (!normalized.includes((`${SPEC_DIR_NAME}/` as const))) {
      return undefined;
    }

    // 策略 1：精确文件名匹配
    const basename = extractBasename(filePath);
    const byName = FILE_NAME_TO_RESOURCE_TYPE.get(basename);
    if (byName !== undefined) {
      return byName;
    }

    // 策略 2：目录片段匹配（保守）
    // 例如 .specforge/work-items/WI-0001/gates/xxx.md → gate_file
    // 例如 .specforge/work-items/WI-0001/evidence/xxx.md → evidence_file
    const segments = normalized.split('/');
    for (let i = segments.length - 2; i >= 0; i--) {
      const segment = segments[i];
      const byDir = DIR_SEGMENT_TO_RESOURCE_TYPE.get(segment);
      if (byDir !== undefined) {
        return byDir;
      }
    }

    // 策略 3：未识别
    return undefined;
  },

  /**
   * 判断文件路径是否为受保护的 spec 文件。
   */
  isSpecFile(filePath: string): boolean {
    return this.match(filePath) === 'spec_file';
  },

  /**
   * 判断文件路径是否为受保护的 evidence 文件。
   */
  isEvidenceFile(filePath: string): boolean {
    return this.match(filePath) === 'evidence_file';
  },

  /**
   * 判断文件路径是否为受保护的 gate 文件。
   */
  isGateFile(filePath: string): boolean {
    return this.match(filePath) === 'gate_file';
  },

  /**
   * 判断文件路径是否为受保护的 decision 文件。
   */
  isDecisionFile(filePath: string): boolean {
    return this.match(filePath) === 'decision_file';
  },

  /**
   * 判断文件路径是否为受保护的 merge 文件。
   */
  isMergeFile(filePath: string): boolean {
    return this.match(filePath) === 'merge_file';
  },

  /**
   * 判断文件路径是否为任何受保护文件。
   */
  isProtected(filePath: string): boolean {
    return this.match(filePath) !== undefined;
  },
} as const;

/**
 * 独立函数形式，方便解构使用。
 */
export function matchProtectedFile(filePath: string): ResourceType | undefined {
  return ProtectedFileMatcher.match(filePath);
}

/**
 * Retry Mechanism Module
 * Provides retry logic with configurable strategies for gate execution
 */

/**
 * Retry Mechanism Module
 * Provides retry logic with configurable strategies for gate execution
 */
import { isGateError } from './error-handler.js';
import type { RetryConfig, RetryState } from './types.js';

/**
 * Default retry configuration
 */
export const DEFAULT_RETRY_CONFIG: Required<RetryConfig> = {
  maxAttempts: 3,
  initialDelayMs: 1000,
  maxDelayMs: 10000,
  backoffMultiplier: 2,
  strategy: 'exponential',
  nonRetryableCodes: [],
  retryableCodes: [],
  onRetry: (_attempt: number, _error: unknown, _delayMs: number) => true,
  onExhausted: (_error: unknown, _attempts: number) => { /* no-op */ },
};

/**
 * Internal full config type with required fields
 */
interface FullRetryConfig {
  maxAttempts: number;
  initialDelayMs: number;
  maxDelayMs: number;
  backoffMultiplier: number;
  strategy: 'fixed' | 'exponential' | 'linear';
  nonRetryableCodes: string[];
  retryableCodes: string[];
  onRetry?: (attempt: number, error: unknown, delayMs: number) => boolean | Promise<boolean>;
  onExhausted?: (error: unknown, attempts: number) => void;
}

/**
 * Calculate delay for the next retry attempt
 * @param attempt Current attempt number (0-indexed)
 * @param config Retry configuration
 * @returns Delay in milliseconds
 */
export function calculateDelay(attempt: number, config: FullRetryConfig): number {
  let delay: number;

  switch (config.strategy) {
    case 'exponential':
      // Exponential backoff: initialDelay * (multiplier ^ attempt)
      delay = config.initialDelayMs * Math.pow(config.backoffMultiplier, attempt);
      break;

    case 'linear':
      // Linear backoff: initialDelay * (attempt + 1)
      delay = config.initialDelayMs * (attempt + 1);
      break;

    case 'fixed':
    default:
      // Fixed delay
      delay = config.initialDelayMs;
      break;
  }

  // Cap at max delay
  return Math.min(delay, config.maxDelayMs);
}

/**
 * Check if an error should be retried based on configuration
 * @param error The error to check
 * @param config Retry configuration
 * @returns true if the error should be retried
 */
export function shouldRetryError(error: unknown, config: FullRetryConfig): boolean {
  // If it's not a GateError, we cannot determine retryability - default to no retry
  if (!isGateError(error)) {
    return false;
  }

  const gateError = error;

  // Check if the error itself is marked as non-retryable
  if (!gateError.retryable) {
    return false;
  }

  // Whitelist mode: only retry if error code is in the list
  if (config.retryableCodes.length > 0) {
    return config.retryableCodes.includes(gateError.code);
  }

  // Blacklist mode: do not retry if error code is in the list
  if (config.nonRetryableCodes.length > 0) {
    return !config.nonRetryableCodes.includes(gateError.code);
  }

  // Default: retry based on error's retryable flag
  return gateError.retryable;
}

/**
 * Sleep for the specified duration
 * @param ms Duration in milliseconds
 */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Execute an operation with retry logic
 * @param operation The async operation to execute
 * @param config Retry configuration
 * @param operationName Optional name for logging
 * @returns The result of the operation
 */
export async function withRetry<T>(
  operation: () => Promise<T> | T,
  config: RetryConfig,
  operationName?: string
): Promise<T> {
  // Merge with defaults
  const fullConfig: FullRetryConfig = {
    maxAttempts: DEFAULT_RETRY_CONFIG.maxAttempts,
    initialDelayMs: DEFAULT_RETRY_CONFIG.initialDelayMs,
    maxDelayMs: DEFAULT_RETRY_CONFIG.maxDelayMs,
    backoffMultiplier: DEFAULT_RETRY_CONFIG.backoffMultiplier,
    strategy: DEFAULT_RETRY_CONFIG.strategy,
    nonRetryableCodes: DEFAULT_RETRY_CONFIG.nonRetryableCodes,
    retryableCodes: DEFAULT_RETRY_CONFIG.retryableCodes,
    ...config,
  };

  // Initialize retry state
  const state: RetryState = {
    attempts: 0,
    lastError: undefined,
    delays: [],
    startTime: Date.now(),
  };

  let lastError: unknown;

  // Try loop with retry logic
  while (state.attempts < fullConfig.maxAttempts) {
    try {
      // Execute the operation
      const result = await operation();

      // Success - return result
      state.endTime = Date.now();
      return result;
    } catch (error) {
      lastError = error;
      state.lastError = error;
      state.attempts++;

      // Check if we should retry
      const canRetry = 
        state.attempts < fullConfig.maxAttempts && 
        shouldRetryError(error, fullConfig);

      if (!canRetry) {
        // No more retries
        state.endTime = Date.now();

        // Call onExhausted callback if provided
        if (fullConfig.onExhausted) {
          try {
            fullConfig.onExhausted(error, state.attempts);
          } catch {
            // Ignore callback errors
          }
        }

        throw error;
      }

      // Calculate delay for next retry
      const delayMs = calculateDelay(state.attempts, fullConfig);
      state.delays.push(delayMs);

      // Call onRetry callback if provided
      let shouldContinue = true;
      if (fullConfig.onRetry) {
        try {
          const result = await fullConfig.onRetry(state.attempts, error, delayMs);
          shouldContinue = result !== false;
        } catch {
          // If callback throws, continue with retry
          shouldContinue = true;
        }
      }

      if (shouldContinue === false) {
        // Retry cancelled by callback
        state.endTime = Date.now();
        throw error;
      }

      // Log retry attempt
      const errorMessage = error instanceof Error ? error.message : String(error);
      const gateErrorInfo = isGateError(error) 
        ? ` (code: ${(error).code}, retryable: ${(error).retryable})`
        : '';

      console.warn(
        `[Retry] ${operationName || 'operation'} failed${gateErrorInfo}, ` +
        `attempt ${state.attempts}/${fullConfig.maxAttempts}, ` +
        `retrying in ${delayMs}ms: ${errorMessage}`
      );

      // Wait before retrying
      await sleep(delayMs);
    }
  }

  // Should not reach here, but just in case
  state.endTime = Date.now();
  throw lastError;
}

/**
 * Create a retry decorator function for use with GateRunner
 * @param config Retry configuration
 * @returns Decorator function
 */
export function createRetryDecorator(config: RetryConfig) {
  return function retryDecorator<T extends (...args: any[]) => any>(
    operation: T,
    operationName?: string
  ): T {
    const decorated = async (...args: Parameters<T>): Promise<ReturnType<T>> => {
      return withRetry(
        () => operation(...args),
        config,
        operationName || operation.name
      );
    };
    return decorated as T;
  };
}

/**
 * Get retry statistics from a RetryState
 * @param state The retry state
 * @returns Statistics object
 */
export function getRetryStats(state: RetryState): {
  attempts: number;
  totalDelayMs: number;
  durationMs: number;
  succeeded: boolean;
  failed: boolean;
} {
  return {
    attempts: state.attempts,
    totalDelayMs: state.delays.reduce((sum, d) => sum + d, 0),
    durationMs: (state.endTime || Date.now()) - state.startTime,
    succeeded: state.endTime !== undefined && state.lastError === undefined,
    failed: state.endTime !== undefined && state.lastError !== undefined,
  };
}

/**
 * Validate retry configuration
 * @param config The configuration to validate
 * @returns Validation errors (empty if valid)
 */
export function validateRetryConfig(config: RetryConfig): string[] {
  const errors: string[] = [];

  if (config.maxAttempts !== undefined) {
    if (config.maxAttempts < 1) {
      errors.push('maxAttempts must be at least 1');
    }
    if (!Number.isInteger(config.maxAttempts)) {
      errors.push('maxAttempts must be an integer');
    }
  }

  if (config.initialDelayMs !== undefined) {
    if (config.initialDelayMs < 0) {
      errors.push('initialDelayMs must be non-negative');
    }
  }

  if (config.maxDelayMs !== undefined) {
    if (config.maxDelayMs < 0) {
      errors.push('maxDelayMs must be non-negative');
    }
  }

  if (config.backoffMultiplier !== undefined) {
    if (config.backoffMultiplier < 1) {
      errors.push('backoffMultiplier must be at least 1');
    }
  }

  if (config.initialDelayMs !== undefined && config.maxDelayMs !== undefined) {
    if (config.initialDelayMs > config.maxDelayMs) {
      errors.push('initialDelayMs must not exceed maxDelayMs');
    }
  }

  return errors;
}

/**
 * Gate Definition Interface — v1.1 标准
 *
 * 产品边界：SPS-1.0。当前可执行合同由本模块导出、Runtime 消费者与回归测试固定；归档 v1.1 标准仅作历史证据。
 *
 * v1.1 新增：
 * - §9.2 Gate 分类枚举
 * - §9.3 hard_gate / soft_gate 类型
 * - §9.4 Gate Report 结构
 * - §9.5 Gate Summary 结构
 * - §9.6 冻结规则
 */

import type {
  GateReport as SharedGateReport,
  GateReportCheck as SharedGateReportCheck,
} from '@specforge/types';

// ---------------------------------------------------------------------------
// §9.2 Gate ID 枚举
// ---------------------------------------------------------------------------

/**
 * v1.1 标准 Gate ID 枚举（§9.2）。
 */
export const GATE_IDS_V11 = [
  'entry_gate',
  'workflow_selection_gate',
  'required_files_gate',
  'candidate_manifest_gate',
  'path_policy_gate',
  'schema_gate',
  'spec_consistency_gate',
  'contract_integrity_gate',
  'trace_gate',
  'workflow_specific_gate',
  'gate_summary_gate',
  'merge_ready_gate',
  'post_merge_gate',
  'verification_gate',
  'formal_version_gate',
  'close_gate',
] as const;

export type GateIdV11 = (typeof GATE_IDS_V11)[number];

// ---------------------------------------------------------------------------
// §9.3 Gate 类型
// ---------------------------------------------------------------------------

/**
 * Gate 严格性类型（§9.3）。
 * - hard_gate: 失败不得进入下一步，不允许 waiver
 * - soft_gate: 可以通过 waiver 继续
 */
export const GATE_STRICTNESS = ['hard_gate', 'soft_gate'] as const;
export type GateStrictness = (typeof GATE_STRICTNESS)[number];

// ---------------------------------------------------------------------------
// §9.4 Gate Report
// ---------------------------------------------------------------------------

/**
 * Gate Report 单个检查项。
 */
export type GateReportCheck = SharedGateReportCheck;

/**
 * Gate Report 结构（§9.4）。
 * 路径：.specforge/work-items/<WI-ID>/gates/<gate_id>.json
 */
export type GateReportV11 = SharedGateReport;

// ---------------------------------------------------------------------------
// §9.5 Gate Summary
// ---------------------------------------------------------------------------

/**
 * Gate Summary overall_status 枚举（§9.5）。
 */
export const GATE_SUMMARY_STATUSES = [
  'passed',
  'passed_with_waiver_required',
  'failed',
  'blocked',
  'expired',
  'invalidated',
] as const;

export type GateSummaryStatus = (typeof GATE_SUMMARY_STATUSES)[number];

// ---------------------------------------------------------------------------
// 原有 Gate Definition 接口（向后兼容）
// ---------------------------------------------------------------------------

/**
 * Gate execution types (how the gate executes its children)
 */
export type GateType = 'simple' | 'composite';

/**
 * Gate kinds (the workflow stage this gate represents)
 */
export type GateKind = 'requirements' | 'design' | 'tasks' | 'verification';

/**
 * Composite Gate execution modes
 */
export type CompositeGateMode = 'sequential' | 'parallel';

/**
 * Composite Gate failure policies
 */
export type FailPolicy = 'fail_fast' | 'collect_all';

/**
 * Gate configuration
 */
export interface GateConfig {
  timeout?: number;
  retryCount?: number;
  retryDelay?: number;
  metadata?: Record<string, unknown>;
}

/**
 * Gate dependencies
 */
export interface GateDependency {
  gateId: string;
  required: boolean;
}

/**
 * Base Gate definition fields
 */
export interface BaseGateDefinition {
  schema_version: "1.0";
  id: string;
  name: string;
  type: GateType;
  kind?: GateKind;
  config?: GateConfig;
  dependencies?: GateDependency[];
}

/**
 * Simple Gate definition
 */
export interface SimpleGateDefinition extends BaseGateDefinition {
  type: 'simple';
  checkFn?: () => Promise<GateResult> | GateResult;
  /** Whether this gate is required (default: true). Non-required gates auto-waive when no checkFn */
  required?: boolean;
  /** Gate severity — 'soft' gates auto-waive when no checkFn */
  severity?: 'hard' | 'soft';
}

/**
 * Composite Gate definition
 */
export interface CompositeGateDefinition extends BaseGateDefinition {
  type: 'composite';
  mode: CompositeGateMode;
  failPolicy: FailPolicy;
  children: GateDefinition[];
}

/**
 * Gate result interface (forward declaration)
 */
export type GateResult = import('./gate-result').GateResult;

/**
 * Union of all Gate definitions
 */
export type GateDefinition = SimpleGateDefinition | CompositeGateDefinition;

/**
 * Workflow Instance Interface
 * Defines the structure for workflow instances
 */

/**
 * Basic workflow event structure (used in WorkflowInstance history)
 */
export interface WorkflowEventData {
  type: string;
  instanceId: string;
  timestamp: Date;
  data?: Record<string, unknown>;
}

/**
 * Workflow instance status
 */
export type WorkflowInstanceStatus = 'pending' | 'running' | 'paused' | 'completed' | 'failed';

/**
 * Workflow instance
 */
export interface WorkflowInstance {
  schema_version: "1.0";
  id: string;
  workflowId: string;
  currentState: string;
  status: WorkflowInstanceStatus;
  history: WorkflowEventData[];
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Workflow execution context
 */
export interface WorkflowContext {
  instance: WorkflowInstance;
  definition: import('./workflow-definition').WorkflowDefinition;
}

import { evaluateMergeReport } from '@specforge/types';
import { SPEC_DIR_NAME } from "@specforge/types/directory-layout";
/**
 * CloseGate.ts — SpecForge v1.1 Close Gate
 *
 * Validates all conditions are met before closing a work item.
 * 10 checks with not_applicable support.
 *
 * Requirements: 7.1-7.14
 */
import { isWorkItemSpecArtifactPlaceholder } from '@specforge/types/directory-layout';

// ---- Types ----

export interface CloseCheck {
  name: string;
  passed: boolean;
  reason?: string | undefined;
  notApplicable?: boolean;
}

export interface CloseValidationResult {
  canClose: boolean;
  failedChecks: string[];
  checks: CloseCheck[];
}

export interface FileSystemValidationParams {
  projectRoot: string;
  workItemId: string;
  currentState: string;
  gatesAllPassed: boolean;
  userDecisionExists: boolean;
  mergeReportContent: string | null;
  specVersionIncremented: boolean;
  hasUnprocessedExtensionRequest: boolean;
  hasUnresolvedEscapedWriteIncident: boolean;
  readFile: (path: string) => string | null;
  fileExists: (path: string) => boolean;
}

/**
 * CloseGate — validates all close conditions.
 *
 * Requirements: 7.1-7.14
 */
export class CloseGate {
  /**
   * Validate all close conditions.
   * Requirements: 7.1-7.10
   */
  validateClose(params: {
    currentState: string;
    gatesAllPassed: boolean;
    userDecisionExists: boolean;
    mergeReportExists: boolean;
    mergeReportAllSuccess: boolean;
    specVersionIncremented: boolean;
    evidenceManifestExists?: boolean;
    verificationReportExists?: boolean;
    traceMatrixUpdated?: boolean;
    hasUnprocessedExtensionRequest: boolean;
    hasUnresolvedEscapedWriteIncident: boolean;
    notApplicableFlags?: Set<string>;
  }): CloseValidationResult {
    const checks: CloseCheck[] = [];
    const failedChecks: string[] = [];
    const naFlags = params.notApplicableFlags ?? new Set<string>();

    // Check 1: State is verification_done (Requirement 7.1)
    const check1: CloseCheck = {
      name: 'state_check',
      passed: params.currentState === 'verification_done',
      reason: params.currentState !== 'verification_done'
        ? `Expected state 'verification_done', got '${params.currentState}'`
        : undefined,
    };
    checks.push(check1);

    // Check 2: All gates passed (Requirement 7.2)
    const check2: CloseCheck = {
      name: 'gates_check',
      passed: params.gatesAllPassed,
      reason: !params.gatesAllPassed ? 'Not all gates passed' : undefined,
    };
    checks.push(check2);

    // Check 3: user_decision.json exists and valid (Requirement 7.3)
    const check3: CloseCheck = {
      name: 'user_decision_check',
      passed: params.userDecisionExists,
      reason: !params.userDecisionExists ? 'user_decision.json not found or invalid' : undefined,
    };
    checks.push(check3);

    // Check 4: merge_report.md exists and all operations successful (Requirement 7.4)
    const check4: CloseCheck = {
      name: 'merge_report_check',
      passed: params.mergeReportExists && params.mergeReportAllSuccess,
      reason: !params.mergeReportExists
        ? 'merge_report.md not found'
        : !params.mergeReportAllSuccess
          ? 'Not all merge operations succeeded'
          : undefined,
    };
    checks.push(check4);

    // Check 5: Project spec version incremented (Requirement 7.5)
    const check5: CloseCheck = {
      name: 'spec_version_check',
      passed: params.specVersionIncremented,
      reason: !params.specVersionIncremented ? 'Project spec version not incremented' : undefined,
    };
    checks.push(check5);

    // Check 6: evidence_manifest.json exists (Requirement 7.6) — can be skipped with not_applicable
    const check6NA = naFlags.has('evidence_check');
    const check6: CloseCheck = {
      name: 'evidence_check',
      passed: check6NA || (params.evidenceManifestExists ?? false),
      notApplicable: check6NA,
      reason: !check6NA && !params.evidenceManifestExists
        ? 'evidence_manifest.json not found'
        : undefined,
    };
    checks.push(check6);

    // Check 7: verification_report.md exists (Requirement 7.7) — can be skipped
    const check7NA = naFlags.has('verification_check');
    const check7: CloseCheck = {
      name: 'verification_check',
      passed: check7NA || (params.verificationReportExists ?? false),
      notApplicable: check7NA,
      reason: !check7NA && !params.verificationReportExists
        ? 'verification_report.md not found'
        : undefined,
    };
    checks.push(check7);

    // Check 8: trace_matrix.md or trace_delta.md updated (Requirement 7.8) — can be skipped
    const check8NA = naFlags.has('trace_matrix_check');
    const check8: CloseCheck = {
      name: 'trace_matrix_check',
      passed: check8NA || (params.traceMatrixUpdated ?? false),
      notApplicable: check8NA,
      reason: !check8NA && !params.traceMatrixUpdated
        ? 'trace_matrix.md or trace_delta.md not updated'
        : undefined,
    };
    checks.push(check8);

    // Check 9: No unprocessed extension_request.json (Requirement 7.9)
    const check9: CloseCheck = {
      name: 'extension_check',
      passed: !params.hasUnprocessedExtensionRequest,
      reason: params.hasUnprocessedExtensionRequest
        ? 'Unprocessed extension_request.json exists'
        : undefined,
    };
    checks.push(check9);

    // Check 10: No unresolved escaped_write_incident (Requirement 7.10)
    const check10: CloseCheck = {
      name: 'write_audit_check',
      passed: !params.hasUnresolvedEscapedWriteIncident,
      reason: params.hasUnresolvedEscapedWriteIncident
        ? 'Unresolved escaped_write_incident exists'
        : undefined,
    };
    checks.push(check10);

    // Collect failures
    for (const check of checks) {
      if (!check.passed && !check.notApplicable) {
        failedChecks.push(check.name);
      }
    }

    return {
      canClose: failedChecks.length === 0,
      failedChecks,
      checks,
    };
  }

  /**
   * Validate close conditions from the filesystem.
   * Reads evidence files from disk instead of accepting booleans.
   * Never uses notApplicableFlags to bypass evidence/verification/trace checks.
   */
  validateFromFileSystem(params: FileSystemValidationParams): CloseValidationResult {
    const workItemDir = `${SPEC_DIR_NAME}/work-items/${params.workItemId}`;

    // Derive booleans from filesystem
    const evidenceManifestPath = `${workItemDir}/evidence/evidence_manifest.json`;
    const verificationReportPath = `${workItemDir}/verification_report.md`;
    const candidateTraceDeltaPath = `${workItemDir}/candidates/trace_delta.md`;
    const legacyTraceDeltaPath = `${workItemDir}/trace_delta.md`;
    const traceDeltaPath = params.fileExists(candidateTraceDeltaPath)
      ? candidateTraceDeltaPath
      : legacyTraceDeltaPath;
    const changedFilesAuditPath = `${workItemDir}/changed_files_audit.json`;

    const evidenceManifestExists = params.fileExists(evidenceManifestPath);
    const verificationReportExists = params.fileExists(verificationReportPath);
    const traceDeltaContent = params.readFile(traceDeltaPath);
    const traceDeltaExists =
      params.fileExists(traceDeltaPath) &&
      traceDeltaContent !== null &&
      !isWorkItemSpecArtifactPlaceholder('trace_delta', traceDeltaContent);
    const changedFilesAuditExists = params.fileExists(changedFilesAuditPath);

    // Validate the persistent report contract and bind it to the current Work Item.
    let mergeReportAllSuccess = false;
    let mergeReportExists = false;
    if (params.mergeReportContent !== null) {
      mergeReportExists = true;
      const verdict = evaluateMergeReport(params.mergeReportContent, params.workItemId);
      mergeReportAllSuccess = verdict.valid &&
        (verdict.status === 'success' || verdict.status === 'not_applicable');
    }

    const checks: CloseCheck[] = [];
    const failedChecks: string[] = [];

    // Check 1: State is verification_done (Requirement 7.1)
    const check1: CloseCheck = {
      name: 'state_check',
      passed: params.currentState === 'verification_done',
      reason: params.currentState !== 'verification_done'
        ? `Expected state 'verification_done', got '${params.currentState}'`
        : undefined,
    };
    checks.push(check1);

    // Check 2: All gates passed (Requirement 7.2)
    const check2: CloseCheck = {
      name: 'gates_check',
      passed: params.gatesAllPassed,
      reason: !params.gatesAllPassed ? 'Not all gates passed' : undefined,
    };
    checks.push(check2);

    // Check 3: user_decision.json exists and valid (Requirement 7.3)
    const check3: CloseCheck = {
      name: 'user_decision_check',
      passed: params.userDecisionExists,
      reason: !params.userDecisionExists ? 'user_decision.json not found or invalid' : undefined,
    };
    checks.push(check3);

    // Check 4: merge_report.md exists and all operations successful (Requirement 7.4)
    const check4: CloseCheck = {
      name: 'merge_report_check',
      passed: mergeReportExists && mergeReportAllSuccess,
      reason: !mergeReportExists
        ? 'merge_report.md not found'
        : !mergeReportAllSuccess
          ? 'Merge report does not indicate success or not_applicable'
          : undefined,
    };
    checks.push(check4);

    // Check 5: Project spec version incremented (Requirement 7.5)
    const check5: CloseCheck = {
      name: 'spec_version_check',
      passed: params.specVersionIncremented,
      reason: !params.specVersionIncremented ? 'Project spec version not incremented' : undefined,
    };
    checks.push(check5);

    // Check 6: evidence_manifest.json exists (Requirement 7.6) — NO notApplicable bypass
    const check6: CloseCheck = {
      name: 'evidence_check',
      passed: evidenceManifestExists,
      reason: !evidenceManifestExists
        ? `evidence_manifest.json not found at ${evidenceManifestPath}`
        : undefined,
    };
    checks.push(check6);

    // Check 7: verification_report.md exists (Requirement 7.7) — NO notApplicable bypass
    const check7: CloseCheck = {
      name: 'verification_check',
      passed: verificationReportExists,
      reason: !verificationReportExists
        ? `verification_report.md not found at ${verificationReportPath}`
        : undefined,
    };
    checks.push(check7);

    // Check 8: trace_delta.md exists (Requirement 7.8) — NO notApplicable bypass
    const check8: CloseCheck = {
      name: 'trace_matrix_check',
      passed: traceDeltaExists,
      reason: !traceDeltaExists
        ? `trace_delta.md not found at ${traceDeltaPath}`
        : undefined,
    };
    checks.push(check8);

    // Check 9: No unprocessed extension_request.json (Requirement 7.9)
    const check9: CloseCheck = {
      name: 'extension_check',
      passed: !params.hasUnprocessedExtensionRequest,
      reason: params.hasUnprocessedExtensionRequest
        ? 'Unprocessed extension_request.json exists'
        : undefined,
    };
    checks.push(check9);

    // Check 10: No unresolved escaped_write_incident (Requirement 7.10)
    const check10: CloseCheck = {
      name: 'write_audit_check',
      passed: !params.hasUnresolvedEscapedWriteIncident,
      reason: params.hasUnresolvedEscapedWriteIncident
        ? 'Unresolved escaped_write_incident exists'
        : undefined,
    };
    checks.push(check10);

    // Additional filesystem check: changed_files_audit.json must exist
    if (!changedFilesAuditExists) {
      const auditCheck: CloseCheck = {
        name: 'changed_files_audit_check',
        passed: false,
        reason: `changed_files_audit.json not found at ${changedFilesAuditPath}`,
      };
      checks.push(auditCheck);
      failedChecks.push('changed_files_audit_check');
    }

    // Collect failures from main 10 checks
    for (const check of checks) {
      if (!check.passed && !failedChecks.includes(check.name)) {
        failedChecks.push(check.name);
      }
    }

    return {
      canClose: failedChecks.length === 0,
      failedChecks,
      checks,
    };
  }
}

