     */
    it('should have valid event structure for all events', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.integer({ min: 2, max: 5 }),
          async (numStates) => {
            const stateNames = Array.from({ length: numStates }, (_, i) => `state${i}`);
