        states: {
          requirements: {
            schema_version: '1.0',
            agent: 'requirements',
            gate: {
              schema_version: '1.0',
              type: 'simple',
              id: 'req-gate',
              name: 'Requirements Gate',
              checkFn: () => Promise.resolve({
