            schema_version: '1.0',
            agent: 'dev',
            gate: {
              schema_version: '1.0',
              type: 'simple',
              id: 'impl-gate',
              name: 'Implementation Gate',
              checkFn: () => Promise.resolve({
                schema_version: '1.0',
                passed: true,
