import { promiseFromSync } from '@specforge/types';
/**
 * Unit tests for GateDefinition interface
 * 
 * Validates: Requirements 2.1 (Gate execution engine)
 */

import { describe, it, expect } from 'vitest';

import type {
  GateDefinition,
  SimpleGateDefinition,
  CompositeGateDefinition,
  GateResult} from '../../src/types.js';


describe('GateDefinition Interface', () => {
  describe('SimpleGateDefinition', () => {
    it('should have required fields', () => {
      const gate: SimpleGateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'test-gate-1',
        name: 'Test Gate',
      };

      expect(gate.schema_version).toBe('1.0');
      expect(gate.type).toBe('simple');
      expect(gate.id).toBe('test-gate-1');
      expect(gate.name).toBe('Test Gate');
    });

    it('should be assignable to GateDefinition', () => {
      const simpleGate: SimpleGateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'simple-gate-1',
        name: 'Simple Gate',
      };

      const gate: GateDefinition = simpleGate;
      expect(gate.type).toBe('simple');
      expect(gate.id).toBe('simple-gate-1');
    });

    it('should support optional checkFn field', () => {
      const gateWithCheckFn: SimpleGateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'gate-with-check',
        name: 'Gate with Check Function',
        checkFn:  () => promiseFromSync(() => (({
          schema_version: '1.0',
          passed: true,
          reason: 'Test passed',
        }))),
      };

      expect(gateWithCheckFn.checkFn).toBeDefined();
    });

    it('should support synchronous checkFn', () => {
      const gateWithSyncCheck: SimpleGateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'gate-sync-check',
        name: 'Gate with Sync Check',
        checkFn: () => ({
          schema_version: '1.0',
          passed: true,
          reason: 'Sync test passed',
        }),
      };

      expect(gateWithSyncCheck.checkFn).toBeDefined();
    });

    it('should validate schema_version field', () => {
      const gate: SimpleGateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'valid-gate',
        name: 'Valid Gate',
      };

      expect(gate.schema_version).toBe('1.0');
    });
  });

  describe('CompositeGateDefinition', () => {
    it('should have required fields', () => {
      const compositeGate: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'composite-gate-1',
        name: 'Composite Gate',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [],
      };

      expect(compositeGate.schema_version).toBe('1.0');
      expect(compositeGate.type).toBe('composite');
      expect(compositeGate.id).toBe('composite-gate-1');
      expect(compositeGate.name).toBe('Composite Gate');
      expect(compositeGate.mode).toBe('sequential');
      expect(compositeGate.failPolicy).toBe('collect_all');
      expect(compositeGate.children).toEqual([]);
    });

    it('should be assignable to GateDefinition', () => {
      const compositeGate: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'composite-gate-2',
        name: 'Composite Gate 2',
        mode: 'parallel',
        failPolicy: 'fail_fast',
        children: [],
      };

      const gate: GateDefinition = compositeGate;
      expect(gate.type).toBe('composite');
      expect(gate.id).toBe('composite-gate-2');
    });

    it('should support all CompositeGateMode values', () => {
      const sequentialGate: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'sequential-gate',
        name: 'Sequential Gate',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [],
      };

      const parallelGate: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'parallel-gate',
        name: 'Parallel Gate',
        mode: 'parallel',
        failPolicy: 'fail_fast',
        children: [],
      };

      expect(sequentialGate.mode).toBe('sequential');
      expect(parallelGate.mode).toBe('parallel');
    });

    it('should support all FailPolicy values', () => {
      const failFastGate: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'fail-fast-gate',
        name: 'Fail Fast Gate',
        mode: 'parallel',
        failPolicy: 'fail_fast',
        children: [],
      };

      const collectAllGate: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'collect-all-gate',
        name: 'Collect All Gate',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [],
      };

      expect(failFastGate.failPolicy).toBe('fail_fast');
      expect(collectAllGate.failPolicy).toBe('collect_all');
    });

    it('should support nested children', () => {
      const childGate: SimpleGateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'child-gate',
        name: 'Child Gate',
      };

      const compositeGate: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'parent-gate',
        name: 'Parent Gate',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [childGate],
      };

      expect(compositeGate.children).toHaveLength(1);
      expect(compositeGate.children[0].type).toBe('simple');
      expect(compositeGate.children[0].id).toBe('child-gate');
    });

    it('should support deeply nested composite gates', () => {
      const innerComposite: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'inner-composite',
        name: 'Inner Composite',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [],
      };

      const outerComposite: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'outer-composite',
        name: 'Outer Composite',
        mode: 'parallel',
        failPolicy: 'fail_fast',
        children: [innerComposite],
      };

      expect(outerComposite.children).toHaveLength(1);
      expect(outerComposite.children[0].type).toBe('composite');
      expect(outerComposite.children[0].id).toBe('inner-composite');
    });
  });

  describe('GateDefinition Union Type', () => {
    it('should accept SimpleGateDefinition', () => {
      const simpleGate: SimpleGateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'simple-union',
        name: 'Simple Union Gate',
      };

      const gate: GateDefinition = simpleGate;
      expect(gate.type).toBe('simple');
    });

    it('should accept CompositeGateDefinition', () => {
      const compositeGate: CompositeGateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'composite-union',
        name: 'Composite Union Gate',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [],
      };

      const gate: GateDefinition = compositeGate;
      expect(gate.type).toBe('composite');
    });

    it('should be used in workflow state definitions', () => {
      const simpleGate: SimpleGateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'workflow-gate',
        name: 'Workflow Gate',
      };

      const workflowState = {
        schema_version: '1.0',
        agent: 'test-agent',
        gate: simpleGate as GateDefinition,
        skills: ['skill-1', 'skill-2'],
      };

      expect(workflowState.gate.type).toBe('simple');
      expect(workflowState.gate.id).toBe('workflow-gate');
    });

    it('should support type narrowing with type guards', () => {
      const simpleGate: GateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'type-guard-simple',
        name: 'Type Guard Simple',
      };

      const compositeGate: GateDefinition = {
        schema_version: '1.0',
        type: 'composite',
        id: 'type-guard-composite',
        name: 'Type Guard Composite',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [],
      };

      if (simpleGate.type === 'simple') {
        expect(simpleGate.id).toBe('type-guard-simple');
      }

      if (compositeGate.type === 'composite') {
        expect(compositeGate.mode).toBe('sequential');
        expect(compositeGate.failPolicy).toBe('collect_all');
      }
    });
  });

  describe('Integration with GateResult', () => {
    it('should produce GateResult from checkFn', async () => {
      const gate: SimpleGateDefinition = {
        schema_version: '1.0',
        type: 'simple',
        id: 'result-gate',
        name: 'Result Gate',
        checkFn:  () => promiseFromSync(() => (({
          schema_version: '1.0',
          passed: true,
          reason: 'Integration test passed',
          details: { test: 'value' },
        }))),
      };

      if (gate.checkFn) {
        const result: GateResult = await gate.checkFn();
        expect(result.schema_version).toBe('1.0');
        expect(result.passed).toBe(true);
        expect(result.reason).toBe('Integration test passed');
        expect(result.details?.test).toBe('value');
      }
    });

    it('should validate GateResult schema_version', () => {
      const result: GateResult = {
        schema_version: '1.0',
        passed: false,
        reason: 'Test failed',
      };

      expect(result.schema_version).toBe('1.0');
      expect(result.passed).toBe(false);
      expect(result.reason).toBe('Test failed');
    });
  });
});

import { promiseFromSync } from '@specforge/types';
/**
 * Unit tests for GateRunner
 */

import { describe, it, expect } from 'vitest';

import {
  SimpleGateRunner,
  CompositeGateRunner,
  createGateRunner,
} from '../../src/GateRunner.js';
import type {
  SimpleGateDefinition,
  CompositeGateDefinition,
  WorkflowContext,
} from '../../src/types.js';

describe('GateRunner', () => {
  describe('SimpleGateRunner', () => {
    it('should execute a simple gate with passing check function', async () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate',
        name: 'Test Gate',
        checkFn:  () => promiseFromSync(() => (({ passed: true, reason: 'Test passed' }))),
      };

      const runner = new SimpleGateRunner(gate);
      const result = await runner.check();

      expect(result.passed).toBe(true);
      expect(result.reason).toBe('Test passed');
    });

    it('should execute a simple gate with synchronous check function', async () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate-sync',
        name: 'Test Sync Gate',
        checkFn: () => ({ passed: true, reason: 'Sync test passed' }),
      };

      const runner = new SimpleGateRunner(gate);
      const result = await runner.check();

      expect(result.passed).toBe(true);
      expect(result.reason).toBe('Sync test passed');
    });

    it('should return default pass when no check function is defined', async () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate-default',
        name: 'Test Gate Default',
      };

      const runner = new SimpleGateRunner(gate);
      const result = await runner.check();

      expect(result.passed).toBe(true);
      expect(result.reason).toContain('No check function defined');
    });

    it('should return failure when check function fails', async () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate-fail',
        name: 'Test Gate Fail',
        checkFn:  () => promiseFromSync(() => (({ passed: false, reason: 'Validation failed' }))),
      };

      const runner = new SimpleGateRunner(gate);
      const result = await runner.check();

      expect(result.passed).toBe(false);
      expect(result.reason).toBe('Validation failed');
    });

    it('should handle errors in check function', async () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate-error',
        name: 'Test Gate Error',
        checkFn:  () => { return promiseFromSync(() => {
          throw new Error('Check function threw an error');
        }); },
      };

      const runner = new SimpleGateRunner(gate);
      const result = await runner.check();

      expect(result.passed).toBe(false);
      expect(result.reason).toContain('test-gate-error');
      expect(result.details?.originalError?.name).toBe('Error');
    });

    it('should store and return context', () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate-context',
        name: 'Test Gate Context',
      };

      const context = { userId: 'test-user', role: 'admin' };
      const runner = new SimpleGateRunner(gate, context);

      expect(runner.getContext()).toEqual(context);
    });

    it('should update context', () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate-context-update',
        name: 'Test Gate Context Update',
      };

      const runner = new SimpleGateRunner(gate, { initial: 'value' });
      runner.setContext({ additional: 'data' });

      expect(runner.getContext()).toEqual({ initial: 'value', additional: 'data' });
    });

    it('should get gate definition', () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate-get',
        name: 'Test Gate Get',
      };

      const runner = new SimpleGateRunner(gate);
      expect(runner.getGate()).toEqual(gate);
    });

    it('should validate gate definition', () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: '',
        name: 'Test Gate Invalid',
      };

      const runner = new SimpleGateRunner(gate);
      // The validation happens at the start of check() which is async
      expect(runner.check()).rejects.toThrow('Gate definition must have an id');
    });
  });

  describe('CompositeGateRunner', () => {
    it('should execute composite gate in sequential mode with all passing', async () => {
      const childGate1: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-1',
        name: 'Child Gate 1',
        checkFn:  () => promiseFromSync(() => (({ passed: true, reason: 'Child 1 passed' }))),
      };

      const childGate2: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-2',
        name: 'Child Gate 2',
        checkFn:  () => promiseFromSync(() => (({ passed: true, reason: 'Child 2 passed' }))),
      };

      const compositeGate: CompositeGateDefinition = {
        type: 'composite',
        id: 'composite-gate',
        name: 'Composite Gate',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [childGate1, childGate2],
      };

      const runner = new CompositeGateRunner(compositeGate);
      const result = await runner.check();

      expect(result.passed).toBe(true);
      expect(result.details?.results).toHaveLength(2);
    });

    it('should fail fast in sequential mode when child fails', async () => {
      const childGate1: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-1',
        name: 'Child Gate 1',
        checkFn:  () => promiseFromSync(() => (({ passed: true, reason: 'Child 1 passed' }))),
      };

      const childGate2: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-2',
        name: 'Child Gate 2',
        checkFn:  () => promiseFromSync(() => (({ passed: false, reason: 'Child 2 failed' }))),
      };

      const childGate3: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-3',
        name: 'Child Gate 3',
        checkFn:  () => promiseFromSync(() => (({ passed: true, reason: 'Child 3 passed' }))),
      };

      const compositeGate: CompositeGateDefinition = {
        type: 'composite',
        id: 'composite-gate-fail-fast',
        name: 'Composite Gate Fail Fast',
        mode: 'sequential',
        failPolicy: 'fail_fast',
        children: [childGate1, childGate2, childGate3],
      };

      const runner = new CompositeGateRunner(compositeGate);
      const result = await runner.check();

      expect(result.passed).toBe(false);
      expect(result.details?.failedGateId).toBe('child-2');
      // Should not execute child 3
      expect(result.details?.results).toHaveLength(2);
    });

    it('should execute composite gate in parallel mode', async () => {
      const childGate1: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-1',
        name: 'Child Gate 1',
        checkFn:  () => promiseFromSync(() => (({ passed: true, reason: 'Child 1 passed' }))),
      };

      const childGate2: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-2',
        name: 'Child Gate 2',
        checkFn:  () => promiseFromSync(() => (({ passed: true, reason: 'Child 2 passed' }))),
      };

      const compositeGate: CompositeGateDefinition = {
        type: 'composite',
        id: 'composite-gate-parallel',
        name: 'Composite Gate Parallel',
        mode: 'parallel',
        failPolicy: 'collect_all',
        children: [childGate1, childGate2],
      };

      const runner = new CompositeGateRunner(compositeGate);
      const result = await runner.check();

      expect(result.passed).toBe(true);
      expect(result.details?.results).toHaveLength(2);
    });

    it('should fail fast in parallel mode when child fails', async () => {
      const childGate1: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-1',
        name: 'Child Gate 1',
        checkFn:  () => promiseFromSync(() => (({ passed: true, reason: 'Child 1 passed' }))),
      };

      const childGate2: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-2',
        name: 'Child Gate 2',
        checkFn:  () => promiseFromSync(() => (({ passed: false, reason: 'Child 2 failed' }))),
      };

      const compositeGate: CompositeGateDefinition = {
        type: 'composite',
        id: 'composite-gate-parallel-fail-fast',
        name: 'Composite Gate Parallel Fail Fast',
        mode: 'parallel',
        failPolicy: 'fail_fast',
        children: [childGate1, childGate2],
      };

      const runner = new CompositeGateRunner(compositeGate);
      const result = await runner.check();

      expect(result.passed).toBe(false);
      expect(result.reason).toContain('fail_fast');
    });

    it('should collect all failures with collect_all policy', async () => {
      const childGate1: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-1',
        name: 'Child Gate 1',
        checkFn:  () => promiseFromSync(() => (({ passed: false, reason: 'Child 1 failed' }))),
      };

      const childGate2: SimpleGateDefinition = {
        type: 'simple',
        id: 'child-2',
        name: 'Child Gate 2',
        checkFn:  () => promiseFromSync(() => (({ passed: false, reason: 'Child 2 failed' }))),
      };

      const compositeGate: CompositeGateDefinition = {
        type: 'composite',
        id: 'composite-gate-collect-all',
        name: 'Composite Gate Collect All',
        mode: 'parallel',
        failPolicy: 'collect_all',
        children: [childGate1, childGate2],
      };

      const runner = new CompositeGateRunner(compositeGate);
      const result = await runner.check();

      expect(result.passed).toBe(false);
      expect(result.details?.failed).toBe(2);
      expect(result.details?.passed).toBe(0);
    });

    it('should handle nested composite gates', async () => {
      const simpleGate: SimpleGateDefinition = {
        type: 'simple',
        id: 'simple-gate',
        name: 'Simple Gate',
        checkFn:  () => promiseFromSync(() => (({ passed: true, reason: 'Simple passed' }))),
      };

      const innerComposite: CompositeGateDefinition = {
        type: 'composite',
        id: 'inner-composite',
        name: 'Inner Composite',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [simpleGate],
      };

      const outerComposite: CompositeGateDefinition = {
        type: 'composite',
        id: 'outer-composite',
        name: 'Outer Composite',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [innerComposite],
      };

      const runner = new CompositeGateRunner(outerComposite);
      const result = await runner.check();

      expect(result.passed).toBe(true);
    });
  });

  describe('createGateRunner factory', () => {
    it('should create SimpleGateRunner for simple gates', () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate',
        name: 'Test Gate',
      };

      const runner = createGateRunner(gate);
      expect(runner).toBeInstanceOf(SimpleGateRunner);
    });

    it('should create CompositeGateRunner for composite gates', () => {
      const compositeGate: CompositeGateDefinition = {
        type: 'composite',
        id: 'test-composite',
        name: 'Test Composite',
        mode: 'sequential',
        failPolicy: 'collect_all',
        children: [],
      };

      const runner = createGateRunner(compositeGate);
      expect(runner).toBeInstanceOf(CompositeGateRunner);
    });

    it('should throw error for unknown gate types', () => {
      // Create an object that doesn't match any known gate type
      const gate = {
        type: 'unknown' as const,
        id: 'test-gate',
        name: 'Test Gate',
      };

      // This will fail at runtime since the type assertion is wrong
      expect(() => createGateRunner(gate as any)).toThrow('Unknown gate type');
    });

    it('should pass context to created runner', () => {
      const gate: SimpleGateDefinition = {
        type: 'simple',
        id: 'test-gate',
        name: 'Test Gate',
      };

      const context = { testKey: 'testValue' };
      const runner = createGateRunner(gate, context);

