            state1: {
              agent: 'test-agent',
              gate: compositeGate,
              skills: [],
            },
          },
        },
        artifacts: [],
      };

      engine.loadWorkflow(definition);
      const instance = engine.createInstance('test-workflow');
      const result = await engine.execute(instance.id);

      expect(result.status).toBe('completed');
    });

    it('should fail fast in sequential mode', async () => {
      const compositeGate: CompositeGateDefinition = {
        type: 'composite',
        id: 'composite1',
        name: 'Composite Gate',
        mode: 'sequential',
        failPolicy: 'fail_fast',
        children: [
          { type: 'simple', id: 'child1', name: 'Child 1', checkFn:  () => promiseFromSync(() => (({ passed: false, reason: 'Failed' }))) },
          { type: 'simple', id: 'child2', name: 'Child 2', checkFn:  () => { return promiseFromSync(() => { throw new Error('Should not be reached'); }); } },
        ],
      };

      const definition: WorkflowDefinition = {
        id: 'test-workflow',
        displayName: 'Test',
        intent: 'Test',
        stateMachine: {
          initial: 'state1',
          states: {
            state1: {
              agent: 'test-agent',
              gate: compositeGate,
              skills: [],
            },
          },
        },
        artifacts: [],
      };

      engine.loadWorkflow(definition);
      const instance = engine.createInstance('test-workflow');
      const result = await engine.execute(instance.id);

      // The workflow completes but the composite gate reports failure
      // Since there's no next state, workflow ends as completed
      expect(result.status).toBe('completed');
    });
  });
});

import { promiseFromSync } from '@specforge/types';
/**
