        stateMachine: {
          schema_version: '1.0',
          initial: 'state1',
          states: {},
        },
        artifacts: [],
      };

      expect(() => engine.loadWorkflow(definition)).toThrow('must have at least one state');
    });
  });

  describe('createInstance', () => {
    it('should create a workflow instance', () => {
      const definition: WorkflowDefinition = {
        schema_version: '1.0',
        id: 'test-workflow',
        displayName: 'Test',
        intent: 'Test',
        stateMachine: {
          schema_version: '1.0',
