  return {
    id: 'v11-test-workflow',
    displayName: 'V11 Test',
    intent: 'test',
    stateMachine: {
      initial: 'created',
      states: {
        created: {
          agent: '',
          gate: { type: 'simple', id: 'noop', name: 'No-op', checkFn: passGate },
